  <img id="thumb" src="shoe.jpg" alt="shoe.jpg">
  <img id="star" src="star.png" alt="">
  <img id="map" src="map.png" alt="Street map with the library marked">
`)
const say = (id) => {
  const img = document.getElementById(id)
  return img.alt.length > 0 && img.alt !== img.getAttribute('src')
}
console.log(say('thumb'), say('star'), say('map'))

