document.body.innerHTML = `
  <button id="btn">Open menu</button>
  <nav id="menu" data-state="closed">Menu items here</nav>
  <style>#menu[data-state="closed"] { display: none; }</style>
`;
const btn = document.querySelector('#btn');
const menu = document.querySelector('#menu');
btn.addEventListener('click', () => {
  menu.dataset.state = menu.dataset.state === 'open' ? 'closed' : 'open';
});

document.body.innerHTML = `
  <button id="mode">Toggle</button>
  <p id="status" data-theme="light">status</p>
`;
const btn = document.querySelector('#mode');
const status = document.querySelector('#status');
btn.addEventListener('click', () => {
  status.dataset.theme = status.dataset.theme === 'light' ? 'dark' : 'light';
});
btn.click();
